#!/usr/bin/env python3
"""Render the calibration report from retained receipts and scoped observations."""
import argparse,json,statistics
from pathlib import Path
from harness import TRIAL

def read(path,default=None):
 p=TRIAL/path
 return json.loads(p.read_text()) if p.exists() else default

def row(folder,system,case,mode):
 return next((r for r in read(folder+'/summary.json',[]) if r['system']==system and r['case']==case and r['mode']==mode),None)

def val(r,key='external_median_s',scale=1,digits=3):
 return f"{r[key]*scale:.{digits}f}" if r else 'Not measured'

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--final',action='store_true');args=ap.parse_args();lines=[]
 def p(s=''):lines.append(s)
 p('# leanR1CS Challenge v2 referee report' if args.final else '# leanR1CS Challenge v2 referee report, live draft');p();p('Trial window: **2026-10-23 18:01:45 to 21:01:45 UTC**. Calibration only, not competition. No push was authorized or performed. Harness: `trial-ref/experiments/challenge/`; raw artifacts and this report: `artifacts/trial/`. The rules and audit were read before the entry interface was published at 18:05 UTC, within the first 30 minutes.');p()
 p('## Verdict');p();p('**Neither system has an eligible scalar score.** The required `((A+B)+(A+held-out))` tree is unavailable under the full challenge contract. Baseline R1CS native-Keccak A/B wallets do not compose with its sparse child format; its measured merge controls use shielded+Merkle. VM first merges A+B under a pair-specific tree, but its node repeats one child instead of composing independent AB and AH children. Later R1CS entries demonstrate one-key first/node reuse and selected held-out applications, but still exclude Falcon. Security certification, complete coordinator rejections and the independent upgrade backend remain unavailable. No control sum is substituted for the score.');p();p('Machine-readable gate status, prerequisites and full observed cost vectors are in [scoreboard.json](scoreboard.json), generated from [score-evidence.json](score-evidence.json). A scalar requires ten distinct complete raw receipts for each required component, at least five rounds, matching medians, independent merge children and unchanged forwarded files. Protocol/security/identity eligibility still requires referee audit; this is not untrusted-host attestation.');p()
 p('## Primary baseline scoreboard');p();p('External warm medians on cores 36-47, 12 threads. First/node/root columns are **scope-labelled controls**, not the missing score. Root is complete two-real-application control acceptance, including decoding and claim settlement.');p();p('| Protocol | System | Wallet A s | Wallet B s | First control s | Node control s | Complete root ms | Eligible score |');p('|---|---|---:|---:|---:|---:|---:|---|')
 for protocol in ['blake2s','keccak']:
  wallet='wallet-complete-abab' if protocol=='blake2s' else 'wallet-keccak-complete-abab';merge='complete-merges-'+protocol
  for system in ['r1cs','vm']:
   p(f"| {protocol} | {system} | {val(row(wallet,system,'A','warm'))} | {val(row(wallet,system,'B','warm'))} | {val(row(merge,system,'first complete control','warm'))} | {val(row(merge,system,'node complete control','warm'))} | {val(row(merge,system,'complete root two real apps control','warm'),scale=1000,digits=2)} | Not measurable |")
 p();p('Each primary wallet protocol has 80 successful requests: ten samples per system/application/mode, five rotating A/B rounds. Each complete merge protocol has ten first, ten node and ten root samples per system, plus 60 cadence requests per system and one VM child-preparation receipt. VM certificates now include ordered claims. R1CS first/node controls use different matrix keys; VM is fixed to its program pair and leaf shapes. Sparse recursion uses rate 1/4, VM recursion 1/2; both wallet witness rates are 1/4, with R1CS auxiliary index rate 1/16. These are not matched security/parameter profiles.');p()
 p('### Wallet cold boundary and resources');p();p('Cold below is a fresh combined process, including compilation/setup. It is an upper-bound control, **not** independently reloadable retained-key-only cold. RSS is maximum observed across both cold and warm samples; bytes include complete public envelope/output sidecars. GiB means 2^30 bytes.');p();p('| Protocol | System | A cold s | B cold s | A max GiB | B max GiB | A max bytes | B max bytes |');p('|---|---|---:|---:|---:|---:|---:|---:|')
 for protocol in ['blake2s','keccak']:
  folder='wallet-complete-abab' if protocol=='blake2s' else 'wallet-keccak-complete-abab';rs=read(folder+'/summary.json',[])
  for system in ['r1cs','vm']:
   a=[r for r in rs if r['system']==system and r['case']=='A'];b=[r for r in rs if r['system']==system and r['case']=='B']
   p(f"| {protocol} | {system} | {val(row(folder,system,'A','cold'))} | {val(row(folder,system,'B','cold'))} | {max(r['peak_rss_max_bytes'] for r in a)/2**30:.3f} | {max(r['peak_rss_max_bytes'] for r in b)/2**30:.3f} | {max(r['file_bytes_max'] for r in a):,} | {max(r['file_bytes_max'] for r in b):,} |")
 p();p('R1CS reduced Falcon fails both wallet caps in both protocols. Observed primary VM wallets fit the caps. R1CS A is close to the 1 GiB cap; polling limitations prevent claiming an exact peak. B remains a decoded-input reduced relation on R1CS. VM parses compressed key/signature payloads with scheme headers implied by fixed code, a narrower interface than unrestricted round-3 encoded inputs.');p()
 cold=read('cold-complete-merges/summary.json',[])
 if cold:
  p('### Repeated process-cold merge controls');p();p('Five rounds and ten samples per row, same complete envelopes. These include setup, internal child preparation and a small Python stdin transport process in the RSS/time boundary. They do not isolate retained-key loading.');p();p('| Protocol | System | First cold s | Node cold s |');p('|---|---|---:|---:|')
  for protocol in ['blake2s','keccak']:
   for system in ['r1cs','vm']:
    select=lambda case:next((r for r in cold if r['protocol_hash']==protocol and r['system']==system and r['case']==case+' complete control'),None)
    p(f"| {protocol} | {system} | {val(select('first'))} | {val(select('node'))} |")
  p()
 p('## One-second cadence');p();p('FCFS arrivals at 1,000 ms for 60 seconds; latency includes queue delay, and throughput includes draining. Fixed-child controls, not the required independent three-application node.');p();p('| Protocol | System | Drain s | Throughput /s | p95 service s | p95 arrival-to-completion s | Unfinished at 60 s |');p('|---|---|---:|---:|---:|---:|---:|')
 for protocol in ['blake2s','keccak']:
  for system in ['r1cs','vm']:
   r=read(f'complete-merges-{protocol}/cadence-{system}/summary.json')
   if r:p(f"| {protocol} | {system} | {r['drain_included_s']:.2f} | {r['throughput_per_s']:.3f} | {r['p95_service_s']:.3f} | {r['p95_latency_s']:.3f} | {r['backlog_at_60s']} |")
 p();p('The earlier R1CS BLAKE control run had p95 latency 1.236 s and one completion beyond 60 s, despite a 0.930 s warm node median. The complete-envelope rerun sustained the cadence. Both observations are retained. Full-Keccak controls clearly accumulate backlog. A sub-second median alone does not define cadence success.');p()
 p('## Admission and roots');p();p('Complete wallet admission with retained public setup, ten samples per row. External times include file decoding and request completion; internal verifier medians are shown separately. These check authenticated proof/output commitments, not an unspecified consumer transaction-validity policy.');p();p('| Protocol | System | A external ms | A internal ms | B external ms | B internal ms |');p('|---|---|---:|---:|---:|---:|')
 for protocol in ['blake2s','keccak']:
  for system in ['r1cs','vm']:
   a=row('admission-'+protocol,system,'A admission','warm');b=row('admission-'+protocol,system,'B admission','warm');iv=lambda r:f"{r['reported_metrics']['verify_ms']['median']:.2f}" if r else 'Not measured'
   p(f"| {protocol} | {system} | {val(a,scale=1000,digits=2)} | {iv(a)} | {val(b,scale=1000,digits=2)} | {iv(b)} |")
 p();p('The 20 ms target is binding on observed external medians. The rule specifies no statistic for admission/root, unlike the merge median, and full merge admission semantics remain incomplete. Thus these are observed target failures, not a claim that the entire admission gate has been calibrated.');p()
 roots=read('root-series-entry-2/summary.json',[])
 if roots:
  p('### One/two/three local applications under one aggregate key');p();p('Entry 2 BLAKE2s shielded/Merkle/hash3 control, five samples per count/mode. One aggregate identity is counted in addition to real applications. This is not the required A/B/held-out workload.');p();p('| Real applications | Matrix identities | Cold root ms | Warm root ms |');p('|---:|---:|---:|---:|')
  for count in [1,2,3]:
   get=lambda mode:next((r for r in roots if r['case']==str(count)+' real applications local root' and r['mode']==mode),None)
   p(f"| {count} | {count+1} | {val(get('cold'),scale=1000,digits=2)} | {val(get('warm'),scale=1000,digits=2)} |")
  p();p('Counting the aggregate identity gives total budgets 20/30/40 ms; counting only real applications gives 10/20/30 ms. These produce different verdicts. The earlier complete three-local-application warm root median was 35.46 ms, versus 21.10 ms in the later sweep; neither is discarded. Shared-host load, caching and timing variation are not isolated enough to attribute that difference to one cause.');p()
 external_roots=read('external-entry8-root-snapshot/summary.json',{})
 if external_roots:
  p('### Entrant-published compact root series (external evidence)');p();p('Entry 8 published fifteen fresh four-leaf trees, five per application count, on entrant cores 0–11 with one warm public server per tree. These are separate from referee-core medians and use A/Keccak-1KiB/MPT, without Falcon. A separate profiling request reports settlement costs. The hash-checked publication is retained in `external-entry8-root-snapshot/`.');p();p('| Real applications | Identities including aggregate | External root ms | Internal root ms |');p('|---:|---:|---:|---:|')
  for count,r in external_roots['root_medians'].items():p(f"| {count} | {int(count)+1} | {r['external_s']*1000:.2f} | {r['internal_s']*1000:.2f} |")
  p()
 p('## Entrants, freezes and held-out applications');p();p('Every revised executable, decoder, retained surface or key gets a separate snapshot and draw. Declared setup dependencies, canonical descriptions and interface notes are copied and hashed, not merely the 32-byte digest. SHA-256 authenticates artifacts; it does not replace required Keccak application IDs. The finite pool and earlier reveals are public, so selecting a precompiled decoder demonstrates finite-pool reuse, not arbitrary future-generator universality.');p();p('| Entry | Scope and result | Eligibility |');p('|---|---|---|');p('| 0 / 1 | Partial interface; entry 1 frozen before its Keccak-1KiB/MPT draw, but no runnable held-out composition. About 366 MiB aggregate retained state. | Ineligible |');p('| 2 | Twenty frozen objects; 90 successful local three-application tree requests. Post-draw MPT/Keccak attempts fail as unsupported decoders, not verifier rejection passes. About 366 MiB aggregate plus 275 MiB application retained files. | Ineligible |');p('| 3 | Fixed-padded encoded Falcon diagnostic; six direct verifier-target mutations rejected. No reusable aggregate key or fresh raw-byte scoring adapter. | Ineligible |')
 for entry in ['entry-4','entry-5','entry-7','entry-8']:
  done=read(entry+'-referee/done.json');manifest=read('freezes/'+entry+'/manifest.json',{});draw=read('heldout-'+entry+'.json',{});retained=manifest.get('aggregate_key',{}).get('retained_bytes');scope=f"Aggregate retained {retained/2**20:.2f} MiB" if retained else 'Not frozen'
  if done:
   trees=sum(bool(read(f'{entry}-referee/{mode}-{rnd}/root/sample.json',{}).get('returncode')==0 and read(f'{entry}-referee/{mode}-{rnd}/admission/sample.json',{}).get('returncode')==0) for mode in ['cold','warm'] for rnd in range(5))
   scope+=f"; {done.get('samples',0)} receipts, {len(done.get('failures',[]))} recorded failures; {trees} completed trees across five cold and five warm rounds; draw {', '.join(draw.get('applications',[]))}"
  else:scope+='; referee measurement pending or incomplete'
  p(f'| {entry.removeprefix("entry-")} | {scope}. No Falcon composition. | Ineligible |')
 external=read('entry-6-external-referee/done.json');p('| 6 | '+('Independently encoded novel post-freeze native graph admitted; four independent witnesses, two first merges, node and root under the frozen key. External witness construction is upstream and unscored.' if external else 'External native-graph interface separately frozen; novel referee graph measurement pending or incomplete.')+' | Ineligible |');p()
 p('### Observed entrant control costs');p();p('Wallet rows pool the indicated local/held-out applications and are not A/B score components. Complete node bytes include root-finalization sidecars.');p();p('| Entry | First warm s | Node warm s | Root cold ms | Root warm ms | Node admission warm ms | Max complete node bytes |');p('|---|---:|---:|---:|---:|---:|---:|')
 for entry in ['entry-2','entry-4','entry-5','entry-7','entry-8']:
  folder=entry+'-referee';scope='local control' if entry=='entry-2' else 'heldout control';get=lambda case,mode:row(folder,entry,case+' '+scope,mode);node=get('node','warm')
  p(f"| {entry} | {val(get('first','warm'))} | {val(node)} | {val(get('root','cold'),scale=1000,digits=2)} | {val(get('root','warm'),scale=1000,digits=2)} | {val(get('admission','warm'),scale=1000,digits=2)} | {node['file_bytes_max'] if node else 'Not measured'} |")
 p();p('Entry 4 completed all ten independent A/MPT/Keccak trees, with every frozen object unchanged. Its public A/MPT/Keccak setup times were 4.436/8.012/3.617 s, but retained application files were 454,789,453 / 631,446,065 / 421,884,905 bytes, each above 64 MiB. Cold wallet RSS reached 8.712 GiB and the shared warm wallet process 10.327 GiB. Key setup derivation was public and finished before fresh private seeds. This establishes those selected A/held-out trees only; Falcon admission remains unavailable. Entry 7 tests canonical-only retention and regeneration, not a retroactive correction to entry 4.');p()
 for entry in ['entry-5','entry-7','entry-8']:
  records=[read(str(path.relative_to(TRIAL))) for path in (TRIAL/(entry+'-referee')).glob('setup-*-retained.json')]
  if records:p(f"{entry} observed per-application retained files: "+', '.join(f"{Path(r['artifacts'][0]['path']).parent.name} {r['total_bytes']:,} bytes" for r in records)+'.')
 p();p('### Compact retention and cold regeneration');p();p('Entries 7 and 8 retain canonical traces and keys, then regenerate public matrices/caches. Cold first/node medians include this work; warm processes retain regenerated state in RAM. Warm wallet RSS below is the shared multi-application process, not an isolated per-wallet attribution.');p();p('| Entry | First cold s | Node cold s | Wallet cold max GiB | Shared warm wallet max GiB |');p('|---|---:|---:|---:|---:|')
 for entry in ['entry-7','entry-8']:
  rs=read(entry+'-referee/summary.json',[]);get=lambda case:row(entry+'-referee',entry,case+' heldout control','cold');rss=lambda mode:max((r['peak_rss_max_bytes'] for r in rs if r['mode']==mode and r['case']=='wallet heldout control'),default=None);fmt=lambda x:f'{x/2**30:.3f}' if x is not None else 'Not measured'
  p(f"| {entry} | {val(get('first'))} | {val(get('node'))} | {fmt(rss('cold'))} | {fmt(rss('warm'))} |")
 p();p('## Fresh shared-statement supplement');p();p('Both supplemental protocols completed 80 shared-input Falcon/MPT samples. Full-Keccak guests use the native instruction and commit the exact shared 64-byte circuit statement. BLAKE2s supplemental VM guests use software Keccak and are explicitly not the primary instruction-enabled baseline.');p();p('| Full Keccak | Falcon warm s | MPT warm s | Falcon max GiB / bytes | MPT max GiB / bytes |');p('|---|---:|---:|---|---|')
 rs=read('exact-wallet-keccak/summary.json',[])
 for system in ['r1cs','vm']:
  app=lambda case:[r for r in rs if r['system']==system and r['case']==case+' exact statement'];b=app('B');m=app('mpt')
  if b and m:p(f"| {system} | {val(next(r for r in b if r['mode']=='warm'))} | {val(next(r for r in m if r['mode']=='warm'))} | {max(r['peak_rss_max_bytes'] for r in b)/2**30:.3f} / {max(r['file_bytes_max'] for r in b):,} | {max(r['peak_rss_max_bytes'] for r in m)/2**30:.3f} / {max(r['file_bytes_max'] for r in m):,} |")
 p();p('R1CS bounded MPT also fails both wallet caps; observed native-Keccak VM cases fit them. The software-Keccak VM MPT control exceeds 1 GiB. Fresh statement equality is observed, not a formal equivalence theorem, and Falcon still differs in parsing obligations. No supplement supplies a VM application-independent key or the required node. Sources: `exact-wallet-{blake2s,keccak}/`, published L6/L7 reports and the hash-checked `protocol-published-snapshots/`. Published lane results are labelled external evidence, never silently mixed with referee-core medians.');p()
 p('## Gate calibration');p();p('| Gate | Calibration | Evidence and practical limit |');p('|---|---|---|');p('| First/node mixed merge, 1 s median | Observed Keccak target binding; matched eligibility uncalibrated | Both primary Keccak controls exceed 1 s; exact required tree, common key and rates remain mismatched. |');p('| Root, 10 ms per identity at 1/2/3 apps | Uncalibrated | Complete roots and local series measured; identity denominator and actual A/B/held-out series missing. |');p('| Wallet RAM, 1 GiB | Binding for R1CS Falcon/MPT; non-binding for observed primary/native VM | Process-group sampled RSS; exact cgroup peak unavailable. Sparse universal padding is also over cap. |');p('| Wallet bytes, 300,000 | Binding for R1CS Falcon/MPT; non-binding for observed VM | Complete envelope and sidecars counted; early proof-only samples superseded. |');p('| Admission, 20 ms | Binding on primary external medians; full scope uncalibrated | Internal/external values differ near cutoff; statistic, transaction semantics and all merge cases unspecified. |');p('| Public application setup, 60 s | Non-binding for observed entry-4 setups; baseline full scope uncalibrated | Three public derivations below 8.1 s; Falcon setup isolation/retained-key reload incomplete. |');p('| Application retained files, 64 MiB | Binding for cache-heavy entrants; compact policy separately tested | Entry 4 per-application files fail; shared aggregate versus application accounting ambiguous. Entry 7 retained application files each fit 64 MiB and regenerates caches on cold startup; this does not imply RAM or cold-time compliance. |');p('| Coordinator rejection suite | Uncalibrated | Partial direct regression coverage; no full soundness claim or full coordinator corpus. |');p('| Independent bit-level upgrade | Uncalibrated | No independent hashed reference backend, complete interchange or cross-version corpus supplied. |');p();p('The coordinator security calculator, classical regime, query/grinding composition budget and independent upgrade drill are not replaced by source constants or historical tests. ZK is not claimed.');p()
 p('## Rejections');p();coverage=read('rejection-coverage.json',{});missing=coverage.get('neither_system_has_runnable_direct_evidence',[]);p('Direct post-proof tests cover wallet proof/statement changes, root ordered-claim omission/duplication/order and identity substitutions. Existing sparse root/recorder probes cover false carried evaluations, keys, child kinds and claim mutations. Auxiliary encoded-Falcon and VM deferred-checker scopes are listed separately. Generator-parser probes, if present, test public derivation admission and do not imply graceful service rejection.');p();p('Cases with no runnable direct evidence in either system: '+(', '.join(missing) if missing else 'see the scope-labelled inventory')+'. Full suite remains **not measurable**. [rejection-coverage.json](rejection-coverage.json) lists every coordinator case, evidence path and limited scope. Regression rejection is not a soundness theorem.');p()
 p('## Harness integrity and reproducibility');p();p('All timed children use `taskset -c 36-47` and both thread variables set to 12; adapters assert the custom pool size. Builds and preparation use cores 48-63 with four Cargo jobs. Host receipts verify distinct physical cores, no SMT siblings in the set, no swap and read-only cgroup v2. The fallback polls simultaneous process-group RSS, recording actual gaps; shared pages can be overcounted, short-lived or escaped descendants missed. A concurrent-child allocation probe exercises group accounting. Shared memory bandwidth/frequency and other calibration lanes are not isolated. A read-only freeze-hash audit at approximately 20:37:30–20:37:57 UTC overlapped entry 8 cold measurements; those samples are retained without causal attribution or silent filtering.');p();p('Raw receipts retain argv, executable hashes, timing boundary, process-group RSS, exit status, stdout/stderr and every forwarded file size/hash. Persistent public preprocessing is distinguished from fresh processes; wallet witness decoding, quotient-hint reconstruction and complete serialization are inside corrected timers. Earlier `wallet-abab/` samples omitted R1CS quotient-hint construction and full transport and are preserved only as incomplete-boundary calibration. No eligible result uses them.');p();p('Four integrity tests pass: a missing key prevents the draw, mutation of a frozen binary prevents the draw, a missing component/nonexistent receipt prevents eligibility, and existing arbitrary files cannot authenticate a fabricated complete score. Remaining limitations include unsupplied prerequisites, declared-dependency completeness and a shared writable local environment; hashes do not prove soundness.');p()
 audit=read('final-receipt-audit.json',{})
 if audit:p();p(f"Retained-artifact audit checked {audit['samples']:,} raw receipts and {audit['forwarded_file_references']:,} forwarded-file references: {len(audit['findings'])} size/hash findings and {len(audit['receipts_finishing_after_deadline'])} receipts finishing beyond the deadline. See `final-receipt-audit.json`; this is artifact integrity only.")
 for folder in ['wallet-complete-abab','wallet-keccak-complete-abab']:
  p('Warm spread from `'+folder+'`: '+ '; '.join(f"{r['system']} {r['case']} {r['external_min_s']:.3f} to {r['external_max_s']:.3f} s" for r in read(folder+'/summary.json',[]) if r['mode']=='warm')+'.')
 p();p('The same R1CS Falcon adapter measured 6.869 s warm in the primary BLAKE run and 5.777 s in the later shared-input supplement; Keccak measured 10.350 s and 9.904 s. Inputs, surrounding application portfolio and host conditions differ, so these are repeatability limits, not pooled estimates or an attributed optimization. Every individual sample remains available.');p()
 p('## Ranked rules feedback');p();p('The highest-impact fixes are below. The full 31-item tagged and ranked list, with stable finding IDs and proposed fixes, is [rules-feedback.md](rules-feedback.md).');p();feedback=(TRIAL/'rules-feedback.md').read_text().splitlines();table=[line for line in feedback if line.startswith('|')];p('\n'.join(table[:14]));p();p('Reproduction and audit entry points: `ENTRY-FORMAT.md`, `host.json`, `source-worktrees.json`, `receipt-inventory.json`, `entry-audit.json`, `heldout-admission.md`, `scoreboard.json`, `rejection-coverage.json`, and each run\'s `provenance.json`, `index.json`, `summary.json`, `done.json` and raw receipts. Harness source and build logs are retained locally. No competition winner is declared. No push was performed.')
 (TRIAL/'referee-report.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps({'report':str(TRIAL/'referee-report.md'),'final':args.final,'lines':len(lines)}))
if __name__=='__main__':main()
